import { z } from 'zod';
import { MAX_CENTAVOS } from '../money';

const centavos = z.number().int('Use whole centavos').positive('Must be greater than zero').max(MAX_CENTAVOS);

export const paymentCreateSchema = z.object({
  /** generated by the form; sending the same key twice returns the first payment instead of a duplicate */
  idempotencyKey: z.string().uuid(),
  studentId: z.string().uuid(),
  amount: centavos,
  allocations: z
    .array(z.object({ chargeId: z.string().uuid(), amount: centavos }))
    .max(50)
    .optional(),
  notes: z
    .string()
    .trim()
    .max(300)
    .nullish()
    .transform((v) => (v ? v : null)),
});
export type PaymentCreateInput = z.input<typeof paymentCreateSchema>;

export const paymentVoidSchema = z.object({
  reason: z.string().trim().min(5, 'Give the reason for voiding (at least 5 characters)').max(500),
});

export const emailReceiptSchema = z.object({
  to: z
    .string()
    .trim()
    .toLowerCase()
    .email('Enter a valid email address')
    .max(254)
    .optional(),
});
